"use strict";
  function infoCard(x){return `<button class="card category-card info-family" type="button" data-route="info/${x.key}"><span class="category-icon">${esc(x.icon)}</span><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p><span class="card-foot">Отвори Инфо →</span></button>`}
  function infoRecordCard(i){return `<article class="result-card info-card"><div><div class="verified">✓ Проверена информация</div><h3>${esc(i.title)}</h3><p>${esc(i.description)}</p><div class="result-meta"><span>${esc(i.type)}</span><span>${esc(i.address)}</span></div><div class="info-source">${esc(i.confirmed)} · ${esc(i.source)}</div></div><div class="result-actions"><button class="button button-soft" data-route="info-detail/${i.id}">Виж детайли</button></div></article>`}
  function renderInfo(){const r=routeInfo(),family=r.parts[1];if(!family){main.innerHTML=pageIntro("Проверена местна информация","Инфо Лом","Шест основни семейства. Всеки факт има owner, източник и състояние на потвърждение.")+`<section class="section"><div class="shell"><div class="grid grid-3">${D.infoFamilies.map(infoCard).join("")}</div><div class="notice notice-info mt-16"><strong>Инфо Лом не е обява</strong>Корекциите се предлагат към specialized Info owner и не променят публичния факт автоматично.</div></div></section>`;return}if(family==="health")return renderInfoHealth();const fam=D.infoFamilies.find(x=>x.key===family);if(!fam)return renderNotFound();const rows=D.infoRecords.filter(x=>x.family===family);main.innerHTML=pageIntro("Инфо Лом",fam.title,fam.text)+`<section class="section"><div class="shell">${crumb([["Инфо Лом","info"],[fam.title,""]])}<div class="toolbar"><input class="toolbar-search" type="search" id="info-search" placeholder="Търси в ${esc(fam.title)}"><span class="badge badge-ok">Източник + последно потвърдено</span></div>${stateGate(rows.length?`<div class="result-list">${rows.map(infoRecordCard).join("")}</div>`:`<div class="empty-state"><h2>Няма показани записи в прототипа</h2><p>Семейството остава част от окончателната структура.</p></div>`,"Няма записи в този Info раздел.")}</div></section>`}
  function renderInfoHealth(){main.innerHTML=pageIntro("Инфо Лом","Здраве","Проверена здравна информация: лекари, стоматолози, аптеки, ветеринари и свързани справки.",button("Здраве и грижа — услуги","marketplace/services?group=health"))+`<section class="section"><div class="shell">${crumb([["Инфо Лом","info"],["Здраве",""]])}<div class="grid grid-3"><button class="card compact-card"><h3>Болница</h3><p>Проверена основна болнична информация.</p></button><button class="card compact-card" data-route="marketplace/services?group=health"><h3>Лекари</h3><p>Лични лекари и специалисти.</p></button><button class="card compact-card"><h3>Аптеки</h3><p>Справочна информация и контакти.</p></button><button class="card compact-card" data-route="marketplace/services?group=health"><h3>Стоматолози</h3><p>Проверени дентални практики.</p></button><button class="card compact-card" data-route="marketplace/services?group=health"><h3>Ветеринарни кабинети / ветеринари</h3><p>Проверени ветеринарни контакти.</p></button><button class="card compact-card"><h3>Ветеринарни аптеки</h3><p>Специализирани местни контакти.</p></button><button class="card compact-card"><h3>Лаборатории</h3><p>Проверени местни лаборатории.</p></button></div><div class="divider"></div><div class="result-list">${D.healthProviders.map(h=>`<article class="result-card"><div><span class="owner-label">Health / Info</span><h3>${esc(h.name)}</h3><p>${esc(h.specialty)}</p><div class="result-meta">${statusBadge(h.status)}<span>${esc(h.kind)}</span></div></div><div class="result-actions"><button class="button button-soft" data-route="health-provider/${h.id}">Детайли</button></div></article>`).join("")}</div></div></section>`}
  function renderInfoDetail(id){const i=D.infoRecords.find(x=>x.id===id);if(!i)return renderNotFound();const fam=D.infoFamilies.find(x=>x.key===i.family);main.innerHTML=pageIntro("Инфо Лом",i.title,i.type,`<button class="button button-soft" data-share="info-detail/${i.id}" data-share-title="${esc(i.title)}">Сподели</button>`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Инфо Лом","info"],[fam?.title||"Раздел",`info/${i.family}`],[i.title,""]])}<div class="detail-block trust-strip"><strong>Проверена информация</strong><br>${esc(i.confirmed)} · Източник: ${esc(i.source)}</div><div class="detail-block"><h2>Данни</h2><div class="facts">${i.phone?`<div class="fact"><span>Телефон</span><strong>${esc(i.phone)}</strong></div>`:""}<div class="fact"><span>Адрес</span><strong>${esc(i.address)}</strong></div>${i.hours?`<div class="fact"><span>Работно време / бележка</span><strong>${esc(i.hours)}</strong></div>`:""}<div class="fact"><span>Статус</span><strong>Потвърдено</strong></div></div></div><div class="detail-block"><h2>За тази информация</h2><p>${esc(i.description)}</p></div></div><aside class="detail-side"><div class="detail-block detail-actions">${i.phone?`<button class="button button-primary" data-action="call" data-phone="${esc(i.phone)}">Обади се</button>`:""}<button class="button button-outline" data-route="correction?target=${encodeURIComponent(i.title)}&owner=info">Предложи корекция</button><button class="button button-outline" data-share="info-detail/${i.id}" data-share-title="${esc(i.title)}">Сподели</button></div><div class="notice notice-warn"><strong>Ако данните са остарели</strong>Корекцията се изпраща за проверка. Публичният факт не се презаписва директно.</div></aside></div></section>`}
  function renderCorrection(){const r=routeInfo(),target=r.params.get("target")||"публичен запис",owner=r.params.get("owner")||"info";main.innerHTML=pageIntro("Корекция","Предложи корекция",`За: ${target}. Това е correction flow, не общ сигнал и не директна редакция.`)+`<section class="section"><div class="shell form-wrap"><div class="form-card"><form class="form-grid proto-form" data-form="correction"><input type="hidden" name="target" value="${esc(target)}"><input type="hidden" name="owner" value="${esc(owner)}">${field("Какво според теб не е актуално?","current",{textarea:true,required:true,min:10,full:true})}${field("Каква е правилната информация?","proposed",{textarea:true,required:true,min:10,full:true})}${field("Източник / доказателство","source",{textarea:true,full:true,placeholder:"Линк, снимка, официален документ или друг проверим източник"})}<div class="form-actions"><button class="button button-outline" type="button" data-route="info">Отказ</button><button class="button button-primary" type="submit">Изпрати корекция</button></div></form></div></div></section>`;bindFormUX()}

  function articleCard(a){const ready=a.readiness==="ready";return `<article class="card"><span class="badge ${ready?"badge-ok":"badge-warn"}">${ready?"Проверено готово":"Кандидат за преглед"}</span><h3>${esc(a.title)}</h3><p class="muted">${esc(a.summary)}</p><button class="button button-soft" type="button" data-route="article/${a.id}">Прочети</button></article>`}
  function renderArticles(){main.innerHTML=pageIntro("Полезно за Лом","Статии и ръководства","Ръководствата обясняват процеса; променливите местни факти остават в Инфо Лом.")+`<section class="section"><div class="shell"><div class="grid grid-3">${D.articles.map(articleCard).join("")}</div><div class="notice notice-info mt-16"><strong>Share readiness</strong>Официално споделяне се активира само за съдържание „Проверено готово“ с canonical public URL.</div></div></section>`}
  function renderArticle(id){const a=D.articles.find(x=>x.id===id);if(!a)return renderNotFound();const ready=a.readiness==="ready";main.innerHTML=pageIntro("Ръководство",a.title,a.summary,ready?`<button class="button button-soft" data-share="article/${a.id}" data-share-title="${esc(a.title)}">Сподели</button>`:`<button class="button button-soft" disabled>Споделяне след проверка</button>`)+`<section class="section"><div class="shell detail-layout"><article class="detail-main"><div class="detail-block"><div class="flex">${ready?`<span class="badge badge-ok">Проверено готово</span>`:`<span class="badge badge-warn">За преглед</span>`}<span class="badge">${esc(a.topic)}</span></div><h2>Практични стъпки</h2><ol>${a.body.map(x=>`<li>${esc(x)}</li>`).join("")}</ol><div class="notice notice-info"><strong>Къде са актуалните местни данни?</strong>Когато ръководството има нужда от телефон, адрес, работно време или официален контакт, то води към Инфо Лом вместо да копира стареещи факти.</div></div></article><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" data-route="info">Провери Инфо Лом</button><button class="button button-outline" data-route="questions">Свързани въпроси</button>${ready?`<button class="button button-outline" data-share="article/${a.id}" data-share-title="${esc(a.title)}">Сподели</button>`:""}</div></aside></div></section>`}

  function questionCard(q){return `<article class="card"><span class="owner-label">Q&A owner</span><h3>${esc(q.title)}</h3><p class="muted">${esc(q.description)}</p><div class="flex"><span class="badge badge-blue">${esc(q.category)}</span><span class="badge">${q.answers.length} ${q.answers.length===1?"отговор":"отговора"}</span></div><button class="button button-soft mt-12" type="button" data-route="question/${q.id}">Отвори въпроса</button></article>`}
  function renderQuestions(){main.innerHTML=pageIntro("Общност","Въпроси и препоръки","Въпросите помагат, когато готов резултат липсва. Те не заменят обявите, фирмите или Инфо Лом.",button("Задай въпрос","ask","button button-primary"))+`<section class="section"><div class="shell"><div class="toolbar"><input class="toolbar-search" id="question-search" type="search" placeholder="Търси въпрос"><div class="segmented"><button class="active">Всички</button><button>С отговор</button><button>Без отговор</button></div></div><div class="grid grid-2" id="question-results">${D.questions.map(questionCard).join("")}</div></div></section>`}
  function renderQuestion(id){const q=D.questions.find(x=>x.id===id);if(!q)return renderNotFound();main.innerHTML=pageIntro("Въпрос",q.title,q.category,`<button class="button button-soft" data-share="question/${q.id}" data-share-title="${esc(q.title)}">Сподели</button>`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main"><div class="detail-block"><span class="badge badge-blue">${esc(q.category)}</span><h2>Въпрос</h2><p>${esc(q.description)}</p></div><div class="detail-block"><div class="section-head"><div><h2>Отговори</h2><p>${q.answers.length?"Одобрени публични отговори.":"Все още няма одобрен отговор."}</p></div></div>${q.answers.length?q.answers.map(a=>`<div class="notice"><strong>${esc(a.author)}</strong>${esc(a.text)}</div>`).join(""):`<div class="empty-state"><h2>Бъди първият, който помага</h2><p>Отговорът ще бъде изпратен за преглед преди публикуване.</p></div>`}</div><div class="detail-block"><h2>Добави отговор</h2><form class="form-grid proto-form" data-form="answer" data-question-id="${esc(q.id)}">${field("Твоят отговор","answer",{textarea:true,required:true,min:10,full:true})}<div class="form-actions"><span class="muted small">Нормален отговор → pending review.</span><button class="button button-primary" type="submit">Изпрати отговор</button></div></form></div></div><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" data-share="question/${q.id}" data-share-title="${esc(q.title)}">Сподели</button><button class="button button-outline" data-route="report?target=${encodeURIComponent(q.title)}&owner=question">Докладвай</button></div></aside></div></section>`;bindFormUX()}
  function renderAsk(){const r=routeInfo(),q=r.params.get("q")||"",cat=r.params.get("category")||"";main.innerHTML=pageIntro("Попитай общността","Задай въпрос","Опиши ясно какво търсиш. Преди изпращане прототипът показва duplicate/canonical предупреждение при подобен въпрос.")+`<section class="section"><div class="shell form-wrap"><div class="form-card"><div id="duplicate-warning" class="notice notice-warn" hidden><strong>Възможно е вече да има подобен въпрос</strong><span id="duplicate-copy"></span><div class="mt-12"><button class="button button-soft" type="button" id="open-duplicate">Отвори съществуващия</button></div></div><form class="form-grid proto-form mt-16" data-form="question">${field("Заглавие на въпроса","title",{required:true,min:10,max:120,full:true,value:q,placeholder:"Например: Кой препоръчва добър електротехник?"})}${selectField("Категория","category",["Майстори и ремонти","Здраве и грижа","Работа","Автомобили","Имоти","Домашни услуги","Красота и лична грижа","Транспорт и доставки","Магазини","Събития","Инфо Лом","Друго"],cat,{required:true,full:true})}${field("Описание","description",{textarea:true,required:true,min:20,full:true,placeholder:"Добави подробности, за да получиш по-точен отговор"})}<label class="check-row field-full"><input type="checkbox" name="consent" required> Прочетох и приемам правилата на общността.</label><div class="form-actions"><button class="button button-outline" type="button" data-route="questions">Отказ</button><button class="button button-primary" type="submit">Изпрати за преглед</button></div></form></div></div></section>`;bindFormUX();bindDuplicateCheck()}

  function searchMatches(q){const n=q.trim().toLocaleLowerCase("bg-BG");if(!n)return [];const out=[];D.listings.forEach(x=>{if([x.title,x.description,x.category,x.subcategory,x.city].join(" ").toLocaleLowerCase("bg-BG").includes(n))out.push({family:"Обяви",title:x.title,text:`${x.type} · ${x.city}`,route:`listing/${x.id}`})});D.firms.forEach(x=>{if([x.name,x.description,x.category].join(" ").toLocaleLowerCase("bg-BG").includes(n))out.push({family:"Фирми",title:x.name,text:`${x.category} · ${x.city}`,route:`firm/${x.id}`})});D.healthProviders.forEach(x=>{if([x.name,x.specialty,x.kind].join(" ").toLocaleLowerCase("bg-BG").includes(n))out.push({family:"Здраве",title:x.name,text:`${x.kind} · ${x.specialty}`,route:`health-provider/${x.id}`})});D.infoRecords.forEach(x=>{if([x.title,x.description,x.type].join(" ").toLocaleLowerCase("bg-BG").includes(n))out.push({family:"Инфо Лом",title:x.title,text:x.description,route:`info-detail/${x.id}`})});D.shops.forEach(x=>{if([x.name,x.category,...x.tags].join(" ").toLocaleLowerCase("bg-BG").includes(n))out.push({family:"Магазини",title:x.name,text:x.category,route:`shop/${x.id}`})});D.questions.forEach(x=>{if([x.title,x.description,x.category].join(" ").toLocaleLowerCase("bg-BG").includes(n))out.push({family:"Въпроси",title:x.title,text:x.category,route:`question/${x.id}`})});D.articles.forEach(x=>{if([x.title,x.summary,x.topic].join(" ").toLocaleLowerCase("bg-BG").includes(n))out.push({family:"Статии",title:x.title,text:x.summary,route:`article/${x.id}`})});return out}
  function renderSearch(){const r=routeInfo(),q=r.params.get("q")||"",matches=searchMatches(q);const grouped=matches.reduce((acc,x)=>((acc[x.family]??=[]).push(x),acc),{});let content="";if(q&&matches.length)content=Object.entries(grouped).map(([family,items])=>`<section class="section-tight"><div class="section-head"><div><h2>${esc(family)}</h2><p>${items.length} резултата</p></div></div><div class="result-list">${items.map(x=>`<article class="result-card"><div><span class="owner-label">${esc(family)}</span><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></div><div class="result-actions"><button class="button button-soft" data-route="${esc(x.route)}">Отвори</button></div></article>`).join("")}</div></section>`).join("");else if(q)content=`<div class="empty-state"><h2>Не намерихме готов резултат</h2><p>Търсенето приключи без подходящ резултат. Сега има смисъл да попиташ общността.</p><button class="button button-primary" data-route="ask?q=${encodeURIComponent(q)}&category=Друго">Попитай Лом</button></div>`;else content=`<div class="empty-state"><h2>Напиши какво търсиш</h2><p>Търсенето комбинира обяви, фирми, Инфо Лом, магазини, здраве, въпроси и готови ръководства.</p></div>`;main.innerHTML=pageIntro("Search V6","Търсене","Една търсачка, много owners. Всеки резултат отваря правилната authoritative повърхност.")+`<section class="section"><div class="shell"><form class="search-bar" data-form="search"><input name="q" value="${esc(q)}" placeholder="Какво търсиш в Лом?" autofocus><button class="button button-primary">Търси</button></form><div class="mt-16">${stateGate(content,"Няма резултати за тази заявка.")}</div></div></section>`}
